// This code processes a single item passed from the "Loop Over Items" node.
const item = $input.item;
const fullTitle = item.json.title || '';

let title = fullTitle;
let pricing = 'Not specified';

// Regex patterns to find different budget formats in the title
const patterns = [
  // (Fixed Price: 200 USD) or (Fixed Price: $200)
  /\(Fixed Price:\s*\$?([\d,]+(?:\.\d{2})?)\s*(?:USD)?\)/i,
  // (Hourly: $25-50) or ($25-50/hr)
  /\((?:Hourly:\s*)?\$([\d,]+(?:\.\d{2})?)-\$?([\d,]+(?:\.\d{2})?)(?:\/hr)?\)/i,
  /\(\$([\d,]+(?:\.\d{2})?)-([\d,]+(?:\.\d{2})?)\s*\/hr\)/i,
  // ($25/hr) or (Hourly: $25)
  /\((?:Hourly:\s*)?\$([\d,]+(?:\.\d{2})?)(?:\/hr)?\)/i,
  // - $100-$500
  /-\s*\$([\d,]+(?:\.\d{2})?)-\$([\d,]+(?:\.\d{2})?)\s*(?:USD)?\s*$/i,
  // $100/hr or $100-200/hr
  /\$([\d,]+(?:\.\d{2})?)(?:-([\d,]+(?:\.\d{2})?))?\s*\/hr\s*$/i,
  // $500 USD or $500
  /\$([\d,]+(?:\.\d{2})?)\s*(?:USD)?\s*$/i,
  // 500 USD
  /([\d,]+(?:\.\d{2})?)\s*USD\s*$/i,
  // 100-500 USD
  /([\d,]+(?:\.\d{2})?)-([\d,]+(?:\.\d{2})?)\s*USD\s*$/i
];

// Try each pattern until a match is found
for (let i = 0; i < patterns.length; i++) {
  const pattern = patterns[i];
  const match = fullTitle.match(pattern);

  if (match) {
    // Remove the matched budget part from the title
    title = fullTitle.replace(match[0], '').trim();

    // Format the pricing based on which pattern matched
    if (i === 0) { // Fixed Price
      pricing = `${match[1]} (Fixed)`;
    } else if (i === 1 || i === 2) { // Hourly range
      pricing = `${match[1]}-${match[2]}/hr`;
    } else if (i === 3) { // Single hourly rate
      pricing = `${match[1]}/hr`;
    } else if (i === 4) { // Range with dash
      pricing = `${match[1]}-${match[2]}`;
    } else if (i === 5) { // Hourly with optional range
      pricing = match[2] ? `${match[1]}-${match[2]}/hr` : `${match[1]}/hr`;
    } else if (i === 6 || i === 7) { // Fixed amount
      pricing = `${match[1]}`;
    } else if (i === 8) { // USD range
      pricing = `${match[1]}-${match[2]}`;
    }

    break; // Stop after the first successful match
  }
}

// Clean up any leftover characters from the title
title = title.replace(/\s*[-|–—]+\s*$/, '').replace(/\s*\(\s*\)\s*/, '').trim();

// Add the new fields to the item's data
item.json.extractedTitle = title;
item.json.extractedPricing = pricing;

// Return the modified item so the workflow can continue
return item;

// This code processes a single item passed from the previous node.
const item = $input.item;
const vollnaLink = item.json.link || '';

let decodedUrl = vollnaLink; // Default to the original link
let source = 'Unknown';     // Default source

try {
  // Look for the real URL inside the 'url=' parameter of the Vollna link
  const urlMatch = vollnaLink.match(/url=([^&]+)/);

  if (urlMatch && urlMatch[1]) {
    let potentialUrl = urlMatch[1];

    // NEW: Repeatedly decode the URL until it's clean
    while (potentialUrl.includes('%')) {
      let newDecoded = decodeURIComponent(potentialUrl);
      // If decoding stops changing the string, break the loop
      if (newDecoded === potentialUrl) {
        break;
      }
      potentialUrl = newDecoded;
    }

    // Check if the fully decoded URL is a valid http/https link
    if (potentialUrl.startsWith('http')) {
       decodedUrl = potentialUrl;
    }
  }

  // Now, determine the source platform based on the decoded URL
  if (decodedUrl.includes('upwork.com')) {
    source = 'Upwork';
  } else if (decodedUrl.includes('freelancer.com')) {
    source = 'Freelancer';
  } else if (decodedUrl.includes('guru.com')) {
    source = 'Guru';
  } else if (decodedUrl.includes('peopleperhour.com')) {
    source = 'PeoplePerHour';
  }

} catch (error) {
  console.log(`Error decoding URL: ${vollnaLink}. Error: ${error.message}`);
  // If an error occurs, the defaults will be used.
}

// Add the new decodedUrl and source fields to the item's data
item.json.decodedUrl = decodedUrl;
item.json.source = source;

// Return the modified item for the next node in the workflow
return item;

// This code extracts a single comparable number from the pricing string.
const item = $input.item;
const pricingStr = item.json.extractedPricing || '0';
let numericBudget = 0;

// Use regex to find the first number in the string.
const match = pricingStr.match(/[\d,]+/);

if (match) {
  // Remove commas and convert to a number.
  numericBudget = parseFloat(match[0].replace(/,/g, ''));
}

item.json.numericBudget = numericBudget;
return item;

// This code IGNORES the node's direct input.
// Instead, it fetches ALL the results from the 'Set Variables' node after the loop has finished.
// This code fetches ALL the results directly from the 'Set Variables' node.
const allItems = $('Set Variables').all();
const successful_jobs = [];
const failed_jobs = [];

for (const item of allItems) {
  // Check for an error object in the item's data.
  if (item.json.error) {
    failed_jobs.push({
      title: item.json.title || 'Title not available',
      error_message: item.json.error.message
    });
  } else {
    // If no error, it's a successful job.
    successful_jobs.push({
      title: item.json.title,
      source: item.json.source,
      budget: item.json.budget,
      url: item.json.url,
      proposal: item.json.proposal
    });
  }
}

// Return a single, clean JSON object for the webhook response.
return [{
  json: {
    status: "complete",
    message: `Processing finished. Found ${successful_jobs.length} successful jobs and ${failed_jobs.length} failures.`,
    successful_jobs: successful_jobs,
    failed_jobs: failed_jobs
  }
}];

// This code fetches ALL results from 'Set Variables' and builds an HTML string.
const allItems = $('Set Variables').all();
let jobsHtml = '';

// Loop through each job object.
for (const item of allItems) {
  if (!item.json.error) {
    const job = item.json;
    let proposalText = 'Proposal not found';

    // Robustly parse the proposal string
    if (job.proposal && typeof job.proposal === 'string') {
      try {
        // Step 1: Remove the markdown fences and trim whitespace
        const jsonString = job.proposal.replace(/```json/g, '').replace(/```/g, '').trim();

        // Step 2: Parse the cleaned string
        const parsedJson = JSON.parse(jsonString);

        // Step 3: Extract the actual proposal text
        proposalText = parsedJson.proposal;
      } catch (e) {
        console.log("Failed to parse proposal:", e.message);
        console.log("Original proposal string:", job.proposal);
        proposalText = 'Error: Could not parse the proposal format.';
      }
    }

    // Append the HTML for the current job.
    jobsHtml += `
      <div class="job-entry">
          <div class="data-point"><span class="label">Job Title:</span> ${job.title}</div>
          <div class="data-point"><span class="label">Budget:</span> ${job.budget}</div>
          <div class="data-point"><span class="label">Job URL:</span> <a href="${job.url}">${job.url}</a></div>
          <div class="data-point"><span class="label">Source:</span> ${job.source}</div>
          <div class="data-point"><span class="label">Proposal:</span> <pre>${proposalText}</pre></div>
      </div>
    `;
  }
}

// Return the final HTML string.
return [{
  json: {
    jobsHtml: jobsHtml
  }
}];
